__all__ = ["AdminTagMapper"]

from app.domain.entities import Tag
from app.presentation.dtos import CreateAdminTagInput


class AdminTagMapper:
    """Turn the admin create-tag request body into a domain tag."""

    @staticmethod
    def to_entity(dto: CreateAdminTagInput) -> Tag:
        # The id is generated by the database model when the tag is persisted.
        return Tag(tag_id=None, tag_name=dto.name, tag_parent_id=dto.parent_id)